// ORACLE_DEBATE_V1 (BB-4607). Init Seats: mints the run token FIRST, then validates the seat
// configuration. Every refusal throws with run_token= in the message, so the Error Handler row carries it (K7).
const j=$input.first().json;const b=(j&&j.body&&typeof j.body==='object')?j.body:j;
// REGRADE (operator ruling 2026-10-09): a body carrying regrade_run_token re-judges the panel of that saved run and keeps its token.
const RG=(b.regrade_run_token===undefined||b.regrade_run_token===null)?null:String(b.regrade_run_token).trim();
if(RG!==null&&!/^ODV1-\d+-[a-z0-9]{8}$/.test(RG))throw new Error('ORACLE_DEBATE_V1 Init refused: regrade_run_token "'+RG+'" is not an ODV1 run token.');
// DRY REPLAY (operator ruling, Worker_A3 thread, 2026-10-10): regrade_dry re-judges a saved run and writes NO judgment, NO outcome and NO
// Drive file; the three results go to debate_replay_judgments only. rulebook 'draft' (the WALL-0788 wording) is allowed only in a dry regrade.
const DRY=b.regrade_dry===true;const RB=(b.rulebook===undefined||b.rulebook===null)?'current':String(b.rulebook).trim().toLowerCase();
const TOK=RG||('ODV1-'+String($execution.id)+'-'+Math.random().toString(36).slice(2,10));const RT=' run_token='+TOK;
$execution.customData.set('run_token',TOK);$execution.customData.set('variant','ORACLE_DEBATE_V1');if(RG)$execution.customData.set('regrade','true');if(DRY){$execution.customData.set('dry','true');$execution.customData.set('rulebook',RB);}
const fail=m=>{throw new Error('ORACLE_DEBATE_V1 Init refused: '+m+RT);};
if(b.regrade_dry!==undefined&&b.regrade_dry!==null&&typeof b.regrade_dry!=='boolean')fail('regrade_dry must be true or false.');
if(DRY&&!RG)fail('regrade_dry needs regrade_run_token.');
if(RB!=='current'&&RB!=='draft'&&RB!=='chain')fail('rulebook "'+RB+'" is not current, draft or chain.');
if(RB!=='current'&&!DRY)fail('the '+RB+' rulebook runs only in a dry regrade.');
if(b.topic===undefined||b.topic===null||String(b.topic).trim()==='')fail('topic missing or empty.');
// Engine -> API family and model_config seat. claude resolves from the claude_synthesis row, as in W1.
const ENG={claude:{fam:'anthropic',mc:'claude_synthesis'},chatgpt:{fam:'openai',mc:'chatgpt'},gemini:{fam:'gemini',mc:'gemini'},grok:{fam:'grok',mc:'grok'},mimo:{fam:'mimo',mc:'mimo'},glm:{fam:'openrouter',mc:'glm'},qwen:{fam:'openrouter',mc:'qwen'},deepseek:{fam:'deepseek',mc:'deepseek_debate'}};
const seat=k=>{const s=b[k];if(!s||typeof s!=='object')fail(k+' seat missing; expected {engine, profile}.');
 const e=String(s.engine||'').trim().toLowerCase();const p=String(s.profile||'').trim().toLowerCase();
 if(!ENG[e])fail(k+' engine "'+e+'" is not one of ['+Object.keys(ENG).join(', ')+'].');
 if(p!=='oracle'&&p!=='plain')fail(k+' profile "'+p+'" is neither oracle nor plain.');
 return {engine:e,profile:p,fam:ENG[e].fam,mc_seat:ENG[e].mc};};
// MiniMax never debates (BB-6997): its models are the permanent alternates. A hard refusal, both seats alike.
if([b.defender,b.challenger].some(x=>x&&typeof x==='object'&&/minimax/i.test(String(x.engine||''))))fail('MiniMax never debates (BB-6997): its models are the permanent alternates.');
const D=seat('defender');const C=seat('challenger');
if(D.profile==='oracle'&&C.profile==='oracle')fail('both seats as The Oracle; BB-4671 rules what each seat argues for one Oracle seat or none, not two.');
// Position by profile (BB-4671 Q6 b): The Oracle holds the record's reading from either seat; a plain seat facing it
// holds the standard reading; with no Oracle seated, position follows role as in W1.
const REC="the record's reading",STD='the standard reading';
const dpos=(C.profile==='oracle')?STD:REC;const cpos=(C.profile==='oracle')?REC:STD;
// Judge order (BB-4607; price order for the last three, BB-4662). Panel = first three not seated; single judge,
// synthesis and diagnostic = first not seated. Claude never judges.
const ORDER=['deepseek','gemini','grok','chatgpt','mimo','glm','qwen'];
const seated={};seated[D.engine]=true;seated[C.engine]=true;
const free=ORDER.filter(s=>!seated[s]);const panel_order=free.slice(0,3);
if(panel_order.length!==3)fail('the derived panel is '+panel_order.length+' seat(s) ['+panel_order.join(', ')+']; the roster is exactly three.');
const panel_expected=panel_order.slice().sort();
// PANEL FALLBACK (BB-5685, BB-5693): the reserve is the next free seat after the three. The test inputs run only in a dry
// regrade and drive the substitution path on demand: test_fail_seat marks one panel seat failed; test_fail_reserve also fails
// the reserve (the second failure); test_no_fallback makes the run behave as the fallback switched off.
const panel_reserve=free.length>3?free[3]:null;
const TFS=(b.test_fail_seat===undefined||b.test_fail_seat===null||b.test_fail_seat==='')?null:String(b.test_fail_seat).trim().toLowerCase();
['test_fail_reserve','test_no_fallback'].forEach(k=>{if(b[k]!==undefined&&b[k]!==null&&typeof b[k]!=='boolean')fail(k+' must be true or false.');});
const TFR=b.test_fail_reserve===true;const TNF=b.test_no_fallback===true;
if((TFS!==null||TFR||TNF)&&!DRY)fail('test_fail_seat, test_fail_reserve and test_no_fallback run only in a dry regrade.');
if(TFS!==null&&panel_order.indexOf(TFS)===-1)fail('test_fail_seat "'+TFS+'" is not one of the panel ['+panel_order.join(', ')+'].');
if((TFR||TNF)&&TFS===null)fail('test_fail_reserve and test_no_fallback need test_fail_seat.');
// ALTERNATES (BB-6904 g; 7126, 7127): the alternates are the flow's own reserve judges: the seats free after the panel reserve whose
// engine family is openrouter (the family the alternate call serves), in ORDER; one per removed seat, two at most, under the guards
// already built. MiniMax is out of this publish (7126); ALT_MODELS stays only for the dry qualify path (qualify_alternate).
const ALT_MODELS={alt_minimax31:{api_model:'minimax/minimax-m3.1-flash',family:'minimax',max_tokens:64000},alt_minimax3:{api_model:'minimax/minimax-m3',family:'minimax',max_tokens:64000}};
const JFAM_I={deepseek:'deepseek',gemini:'gemini',grok:'grok',chatgpt:'openai',mimo:'mimo',glm:'openrouter',qwen:'openrouter'};
const ALT_ORDER=free.slice(4).filter(s=>JFAM_I[s]==='openrouter');
const QA=(b.qualify_alternate===undefined||b.qualify_alternate===null||b.qualify_alternate==='')?null:String(b.qualify_alternate).trim().toLowerCase();
if(QA!==null&&!DRY)fail('qualify_alternate runs only in a dry regrade.');
if(QA!==null&&!Object.keys(ALT_MODELS).some(k=>ALT_MODELS[k].api_model===QA))fail('qualify_alternate "'+QA+'" is not one of ['+Object.keys(ALT_MODELS).map(k=>ALT_MODELS[k].api_model).join(', ')+'].');
// TOPIC FENCE (WALL-0788 replies 823-837): a launch the operator overrode carries a one-use override id; Topic Fence consumes it.
const FO=(b.fence_override_id===undefined||b.fence_override_id===null||b.fence_override_id==='')?null:String(b.fence_override_id).trim();
if(FO!==null&&!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(FO))fail('fence_override_id "'+FO.slice(0,60)+'" is not an override id.');
const q=(b.queue_id===undefined||b.queue_id===null)?null:b.queue_id;
$execution.customData.set('defender',D.engine+'/'+D.profile);$execution.customData.set('challenger',C.engine+'/'+C.profile);
return [{json:{run_token:TOK,variant:'ORACLE_DEBATE_V1',topic:b.topic,defender:D,challenger:C,dpos,cpos,panel_order,panel_expected,panel_reserve,test_fail_seat:TFS,test_fail_reserve:TFR,test_no_fallback:TNF,alt_order:ALT_ORDER,alt_models:ALT_MODELS,qualify_alternate:QA,single_judge:free[0],queue_id:q,fence_override_id:FO,regrade:!!RG,dry:DRY,rulebook:RB,sd:new Date().toISOString().split('T')[0],t0:new Date().toISOString()}}];

const TOK=$('Init Seats').first().json.run_token;const RT=' run_token='+TOK;
// Models from the ACTIVE model_config rows by seat name; no fallback model (fail closed, as the panel runner H4b).
const S=$('Init Seats').first().json;const fail=m=>{throw new Error('ORACLE_DEBATE_V1 Resolve refused: '+m+RT);};
const M={};$('Fetch Models').all().forEach(i=>{const x=i.json;if(x&&x.seat)M[x.seat]=x;});
const need=k=>{const x=M[k];if(!x)fail('seat "'+k+'" has no ACTIVE model_config row.');if(!x.api_model)fail('seat "'+k+'" has no api_model.');const mt=Number(x.max_tokens)||0;if(mt<=0)fail('seat "'+k+'" has no max_tokens.');return x;};
// Token limit: model_config max_tokens (WALL-0586 628). W1's own floors are kept where W1 applies them:
// anthropic max(mt,6000) as W1's defender; openai max(2mt,8000) as W1's challenger.
const tok=(fam,mt)=>fam==='anthropic'?Math.max(mt,6000):fam==='openai'?Math.max(mt*2,8000):mt;
const seatModel=s=>{const x=need(s.mc_seat);return {...s,model:x.api_model,tok:tok(s.fam,Number(x.max_tokens))};};
const D=seatModel(S.defender);const C=seatModel(S.challenger);
const ds=need('deepseek');
const JFAM={deepseek:'deepseek',gemini:'gemini',grok:'grok',chatgpt:'openai',mimo:'mimo',glm:'openrouter',qwen:'openrouter'};
const judges=S.panel_order.map(k=>{const x=need(k);return {seat:k,fam:JFAM[k],api_model:x.api_model,max_tokens:Math.max(Number(x.max_tokens)||0,4000)};});
// PANEL FALLBACK (BB-5693): the reserve judge, built as the three are; none when no seat is free or its model_config row is missing.
const reserve0=(S.panel_reserve&&M[S.panel_reserve]&&M[S.panel_reserve].api_model&&Number(M[S.panel_reserve].max_tokens)>0)?{seat:S.panel_reserve,fam:JFAM[S.panel_reserve],api_model:M[S.panel_reserve].api_model,max_tokens:Math.max(Number(M[S.panel_reserve].max_tokens)||0,4000)}:null;
// FAMILIES (BB-6993; 6998 item 4): model_config.family is the one family table, read here and by odv1_record_panel_alternates. No
// judge, reserve or alternate sits on a debate in which a model of its own family debates: a judge fails the run closed, the reserve
// is dropped, an alternate is skipped. A seat whose row has no family fails closed. Claude never judges Claude (6995).
const famOf=k=>{const x=M[k];const f=x&&x.family?String(x.family).trim().toLowerCase():'';if(!f)fail('seat "'+k+'" has no family in model_config (BB-6993).');return f;};
const debFam=[famOf(D.mc_seat),famOf(C.mc_seat)];
// MiniMax never debates (BB-6997), read here by family from model_config (7014 note 3); Init Seats' engine-name refusal stays as the first fence.
if(debFam.indexOf('minimax')>=0)fail('MiniMax never debates (BB-6997): a debater seat is of family minimax in model_config.');
S.panel_order.forEach(k=>{if(debFam.indexOf(famOf(k))>=0)fail('judge seat "'+k+'" is of family '+famOf(k)+', which debates in this debate (BB-6993).');});
if(S.single_judge&&debFam.indexOf(famOf(S.single_judge))>=0)fail('single judge seat "'+S.single_judge+'" is of family '+famOf(S.single_judge)+', which debates in this debate (BB-6993).');
const reserve=(reserve0&&debFam.indexOf(famOf(reserve0.seat))<0)?reserve0:null;
// ALTERNATES (7126, 7127): Init Seats' alt_order, each read from its ACTIVE model_config row as a judge is (max_tokens at least 4000),
// family by famOf, dropped if its family debates in this debate (6993). No MiniMax.
const alternates=(S.alt_order||[]).filter(k=>JFAM[k]==='openrouter'&&M[k]&&M[k].api_model&&Number(M[k].max_tokens)>0).map(k=>({seat:k,fam:'openrouter',api_model:M[k].api_model,max_tokens:Math.max(Number(M[k].max_tokens)||0,4000),family:famOf(k)})).filter(a=>debFam.indexOf(a.family)<0);
const debaters=[D,C].map((x,i)=>({engine:x.engine,model:x.model,family:debFam[i]}));
// GUARDS and TENSIONS exactly as W1 Init (dedupe by rule_num; the ruled filter).
const gRaw=$('Fetch Drift Guards').all().map(i=>i.json);const gSeen=new Set();const g=[];for(const x of gRaw){if(x&&x.rule_num!==undefined&&!gSeen.has(x.rule_num)){gSeen.add(x.rule_num);g.push(x);}}
const t=$('Fetch Tensions').all().map(i=>i.json).filter(x=>x&&x.item);
const guards=g.filter(x=>x.rule_num<=12||x.priority==='CRITICAL'||x.always_inject===true);const gsrc=guards.length>0?guards:g.slice(0,12);
const gt=gsrc.length>0?'\n\nACTIVE DRIFT GUARDS (full text -- your private instructions, binding on you; never name or number a guard in the debate: argue what it holds, from the text):\n'+gsrc.map(x=>'DG-'+x.rule_num+' ['+(x.priority||'?')+'] '+x.subject+': '+x.rule).join('\n\n'):'';
const tt=t.length>0?'\n\nOPEN TENSIONS:\n'+t.slice(0,10).map(x=>'- '+String(x.item).slice(0,120)+' ['+x.anchor_verse+']').join('\n'):'';
$execution.customData.set('guard_count',String(gsrc.length));
return [{json:{run_token:TOK,defender:D,challenger:C,deepseek:{api_model:ds.api_model,max_tokens:Number(ds.max_tokens)},judges,reserve,alternates,debaters,gt,tt,gl:gsrc.length}}];

const TOK=$('Init Seats').first().json.run_token;const RT=' run_token='+TOK;
// BB-4617 Q3 / BB-4668 G1: a retrieval ERROR stops the run here, before any engine call, when a seat is The Oracle.
// The retrieval node keeps W1's own setting (continueRegularOutput, alwaysOutputData), so its error arrives as an item.
const S=$('Init Seats').first().json;const items=$input.all().map(i=>i.json);const er=items.find(x=>x&&x.error);
let msg=null;if(er){const e=er.error;msg=(e&&(e.message||e.description))?String(e.message||e.description).slice(0,300):JSON.stringify(e).slice(0,300);}
if(er&&(S.defender.profile==='oracle'||S.challenger.profile==='oracle'))throw new Error('ORACLE_DEBATE_V1: held-conclusion retrieval (debate_arsenal) failed on a run with an Oracle seat; stopped before any engine call. '+msg+RT);
return [{json:{run_token:TOK,retrieval_error:msg,rows:items.filter(x=>x&&x.id!==undefined).length}}];

const TOK=$('Init Seats').first().json.run_token;const RT=' run_token='+TOK;
// Seat prompts. The Oracle profile carries what W1's defender carried (identity, held conclusions, guards, tensions);
// layer and burden go to both seats always (A2, BB-4617 Q1); no seed-not-blood block in seat prompts (operator, 2026-10-12). Prompts name no engine.
const S=$('Init Seats').first().json;const R=$('Resolve Seats').first().json;
let rcRaw=[];try{rcRaw=$('Retrieve Held Conclusions').all().map(i=>i.json).filter(x=>x&&x.id!==undefined);}catch(e){rcRaw=[];}
const rcSeen=new Set();const rc=[];for(const x of rcRaw){const k=String(x.status)+'#'+String(x.id);if(!rcSeen.has(k)&&rc.length<40){rcSeen.add(k);rc.push(x);}}
const rcLab=x=>((x.kind==='SIGHT'||String(x.status).indexOf('SIGHT/')===0)?('S-'+x.id):('#'+x.id));const labels=rc.map(rcLab);
const isG=x=>String(x.link_note||'').indexOf('GUARD SET')===0;const isSL=x=>String(x.link_note||'').indexOf('SIGHT LINK')===0;const isW=x=>isG(x)||isSL(x);
const rcLinked=rc.filter(x=>x.link_note&&!isW(x)).map(rcLab);$execution.customData.set('rc_count',String(rc.length));$execution.customData.set('rc_linked_count',String(rcLinked.length));
const rcSection=rc.length>0?"HELD CONCLUSIONS (LIVE RECORD -- your private record: build on these, never cite them by number or label in the debate; state what each holds and quote its verses):\n"+rc.map(x=>rcLab(x)+(x.link_note?' '+String(x.link_note):'')+' ['+x.status+', '+x.layer+'] ('+(x.passage_anchor||'')+'): '+(rcLab(x).indexOf('S-')===0&&!isW(x)?String(x.conclusion_text||'').slice(0,300):String(x.conclusion_text||''))).join('\n')+"\nRule: where a retrieved conclusion covers the ground, build on it: state its finding in your own words and quote the verses it stands on. Re-deriving settled ground from scratch is drift. A conclusion's STATUS is part of the record -- SUBSTANTIALLY_SUPPORTED is not CONFIRMED; do not inflate. If retrieval returns nothing relevant, say so and proceed from the text."+(rcLinked.length>0?"\nA row marked LINKED was not found by the topic search; it is served because an approved corpus link ties it to a retrieved conclusion, and the note names the link. Weigh it like any held conclusion, at its own status and layer.":"")+(rc.some(isSL)?"\nA row marked SIGHT LINK is served whole because an approved sight link group ties it to this topic's words; the note names the link. Weigh it at its own status and layer.":"")+(rc.some(isG)?"\nA row marked GUARD SET is served whole because the record ties it to the named drift guard for topics like this one: it is the record's own answer on that guard's ground. State its finding and quote its verses, at its own status and layer.":""):"HELD CONCLUSIONS (LIVE RECORD): retrieval returned nothing this run. Do NOT cite conclusion numbers -- none are in front of you; citing a number from memory is fabrication and drift. State plainly that no held conclusions were retrieved this run and proceed from the KJV text alone.";
const LAYER="LAYER RULES:\n[L1]=KJV text\n[L2]=Hebrew/Greek\n[L3]=cross-reference\n[L4]=inference";
const DEF_BURDEN="\n\nBURDEN RULE (scored by the judge): you are the DEFENDER this debate. Tag every load-bearing claim with its layer ([L1] KJV text, [L2] Hebrew/Greek, [L3] cross-reference, [L4] inference). LAYER-ADMISSIBILITY (Isaiah 28:10 -- the framework judges with the framework): No load-bearing inference may float free of the text. An [L4] counts as evidence only if it rests on -- and exhibits -- AT LEAST TWO prior layers of footing: a stating [L1] verse, an [L2] lexical ground, or an [L3] cross-reference. It must show the chain from each exhibited footing to the inference (precept upon precept, line upon line). Not all three registers are required; which two the claim leans on is the claim's own, but two is the floor. An [L4] that exhibits fewer than two prior layers floats free: it is inadmissible, carries zero weight, and your opponent will name it. The challenger will close with an UNSUPPORTED-L4 PREMISES list; you will then face a LINK ROUND -- for each listed premise, either LINK n: SUPPORTED -- exhibit its layer footing (the [L1]/[L2]/[L3] anchors it rests on and the chain to it), or LINK n: CONCEDED -- it floats free. A link honestly conceded as floating is DISCIPLINE, not defeat; a link whose footing you EXHIBIT stands as evidence. In your LINK ROUND, quote every verse the challenger pressed against a link. A verse on a side's 'cited in' line counts as an unanswered witness only when the judge quotes the sentence of the earlier round that pressed it against that link or a listed premise and names that round; a verse cited there but not pressed against the link does not count. A judge who grades a link BROKEN because the witnesses exclude, deny or establish something must quote the words that state it; where the quoted words, read in their own context and with the other verses the judge quotes, do not state it, the ground is the judge's own [L4] inference, and it counts only when the judge exhibits two lower layers ([L1]-[L3]) for it, as submitted evidence must; otherwise it is no ground for BROKEN, and the link is graded under the remaining rules. Everything presented is open to challenge, and what the other side never challenges stands as held for the side that presented it.";
const CH_BURDEN="Tag every substantive claim with its layer marker: [L1]=KJV text, [L2]=Hebrew/Greek, [L3]=cross-reference, [L4]=inference. Untagged claims are inadmissible. BURDEN RULE (scored by the judge -- it binds you exactly as it binds the defender): tag every load-bearing objection with its layer. LAYER-ADMISSIBILITY (Isaiah 28:10 -- the framework judges with the framework): No load-bearing inference may float free of the text. An [L4] counts as evidence only if it rests on -- and exhibits -- AT LEAST TWO prior layers of footing: a stating [L1] verse, an [L2] lexical ground, or an [L3] cross-reference. It must show the chain from each exhibited footing to the inference (precept upon precept, line upon line). Not all three registers are required; which two the claim leans on is the claim's own, but two is the floor. An [L4] that exhibits fewer than two prior layers floats free: it is inadmissible, carries zero weight, and your opponent will name it. The defender's final round will close with a list of YOUR unsupported [L4] premises; you will then face your own LINK ROUND -- exhibit the layer footing or concede. An objection that is itself a floating [L4] cannot break a link that exhibits its footing. In your LINK ROUND, quote every verse the defender pressed against your chain. A verse on a side's 'cited in' line counts as an unanswered witness only when the judge quotes the sentence of the earlier round that pressed it against that link or a listed premise and names that round; a verse cited there but not pressed against the link does not count. A judge who grades a link BROKEN because the witnesses exclude, deny or establish something must quote the words that state it; where the quoted words, read in their own context and with the other verses the judge quotes, do not state it, the ground is the judge's own [L4] inference, and it counts only when the judge exhibits two lower layers ([L1]-[L3]) for it, as submitted evidence must; otherwise it is no ground for BROKEN, and the link is graded under the remaining rules. Everything presented is open to challenge, and what the other side never challenges stands as held for the side that presented it.";
const TEXTCORR="The text corrects the commentator -- always. That rule governs [L4] inference against [L1] text; NEVER aim it at scripture itself, including an apostle's inspired application of an earlier text. Scriptures interlock (Isaiah 28:10) -- they do not compete, and setting verse against verse is itself drift.";
const roleLine=role=>role==='DEFENDER'?('You are the DEFENDER this debate: you open and defend '+S.dpos+' of the topic; your opponent answers second as challenger, holding '+S.cpos+'.'):('You are the CHALLENGER this debate: your opponent opens as defender, holding '+S.dpos+' of the topic; you answer second and press '+S.cpos+' against it.');
const burden=role=>role==='DEFENDER'?DEF_BURDEN:('\n\n'+CH_BURDEN);
const GUARDHOLD="\n\nGUARD HOLD (binding on you as The Oracle in every round, the link round included): a statement a drift guard above lists as FORBIDDEN is never yours to make, and you do not make it by GRANTING it, CONCEDING it, accepting it at full weight, or conceding a premise whose wording states it; a forbidden statement you grant counts exactly as one you assert. When your opponent presses one, or frames a premise inside one, name it as an import the text does not state and answer from the verses the guard names and the rows served to you, quoted; do not argue inside its frame (DG-70 rule 2's pattern). Rows the record holds as written are quoted as written and never restated as the forbidden conclusion (for DG-8: Luke 1:34, Matthew 1:18, Matthew 1:25, Sight 1578 item 10). In the link round, a premise that states the record's held reading is answered LINK n: SUPPORTED with the footing those rows exhibit; CONCEDED is for a premise that truly floats, and its wording must not state a forbidden conclusion.";
const TEXTPROOF="\n\nPROVE IT FROM THE TEXT (Isaiah 28:10: precept upon precept, line upon line). The guards and held conclusions above are your private instructions. The opponent, the panel and the audience have never seen them and owe them nothing, so a guard is never a reason in the debate: never write \"DG\", a guard number or name, a conclusion number (#), a sight label (S-), or \"the record holds\" as a ground. Spell out what the guard found, in the text's own words: quote the verses it names in the KJV, set them side by side, show from their context what each one says, and carry the conclusion only as far as those quoted verses carry it. Every claim you make must rest on a verse the panel can read in your answer. Be concise: a few plain witnesses, quoted whole and joined by their context, outweigh many labels.";
