 const BOOKS="Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi|Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation".split('|');
 const key=s=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'');
 const BK={};BOOKS.forEach(b=>{BK[key(b)]=b;});
 Object.assign(BK,{psalm:'Psalms',song:'Song of Solomon',gen:'Genesis',exod:'Exodus',exo:'Exodus',ex:'Exodus',lev:'Leviticus',num:'Numbers',deut:'Deuteronomy',dt:'Deuteronomy',josh:'Joshua',judg:'Judges','1sam':'1 Samuel','2sam':'2 Samuel','1kgs':'1 Kings','2kgs':'2 Kings','1chr':'1 Chronicles','2chr':'2 Chronicles',neh:'Nehemiah',esth:'Esther',ps:'Psalms',psa:'Psalms',prov:'Proverbs',eccl:'Ecclesiastes',isa:'Isaiah',jer:'Jeremiah',lam:'Lamentations',ezek:'Ezekiel',dan:'Daniel',hos:'Hosea',mic:'Micah',hab:'Habakkuk',zech:'Zechariah',mal:'Malachi',matt:'Matthew',mt:'Matthew',mk:'Mark',lk:'Luke',jn:'John',rom:'Romans','1cor':'1 Corinthians','2cor':'2 Corinthians',gal:'Galatians',eph:'Ephesians',phil:'Philippians',col:'Colossians','1thess':'1 Thessalonians','2thess':'2 Thessalonians','1tim':'1 Timothy','2tim':'2 Timothy',heb:'Hebrews',jas:'James','1pet':'1 Peter','2pet':'2 Peter','1jn':'1 John',rev:'Revelation','1chron':'1 Chronicles','2chron':'2 Chronicles',hag:'Haggai'});
 const verses=(c,v,tail)=>{const out=[+v];let last=+v;for(const m of String(tail||'').matchAll(/([–—-]|,)\s?(\d{1,3})(?!\d|:)/g)){const n=+m[2];if(m[1]===','){out.push(n);last=n;}else{for(let x=last+1;x<=n&&x-last<=12;x++)out.push(x);last=n;}}return out.map(x=>c+':'+x);};
 const TAIL='((?:\\s?[–—-]\\s?\\d{1,3}(?![\\d:])|\\s?,\\s?\\d{1,3}(?![\\d:]|\\s+[A-Z]))*)';
 // Every verse a text names. Book-named ("Luke 2:33, 41") carry their book; bare ("(1:34)", "2:41") inherit the nearest book named before them in the same text, if any.
 const refs=t=>{const T=String(t||'');const out=[];const RE=new RegExp('(?<![A-Za-z0-9:])(?:((?:[1-3]\\s)?[A-Z][a-z]+(?:\\s(?:of\\s)?[A-Z][a-z]+)?)\\.?\\s)?(\\d{1,3}):(\\d{1,3})'+TAIL,'g');let lastBook=null;
  for(const m of T.matchAll(RE)){let b=m[1]?BK[key(m[1])]:null;if(m[1]&&!b){const w=m[1].split(/\s/).pop();b=BK[key(w)]||null;}
   if(b)lastBook=b;const tail=String(m[4]||'');const parts=tail.split(',');const rng=parts[0];
   const head=verses(m[2],m[3],rng);out.push({book:b,cv:head[0],cvs:head,label:m[2]+':'+m[3]+rng.replace(/\s/g,''),ctx:b||lastBook});
   for(const c of parts.slice(1)){const mm=c.match(/(\d{1,3})(\s?[–—-]\s?\d{1,3})?/);if(!mm)continue;const vv=verses(m[2],mm[1],mm[2]||'');out.push({book:b,cv:vv[0],cvs:vv,label:m[2]+':'+mm[1]+(mm[2]||'').replace(/\s/g,''),ctx:b||lastBook});}}return out;};
 // 6643 (b): each answering reference is filed by chapter:verse, with the book it names explicitly, or as bare when it names none.
 const namedIn=t=>{const s=new Map();for(const r of refs(t))for(const cv of r.cvs){if(!s.has(cv))s.set(cv,{books:new Set(),bare:false,inh:new Set()});const f=s.get(cv);if(r.book)f.books.add(r.book);else{f.bare=true;if(r.ctx)f.inh.add(r.ctx);}}return s;};
 // Named (BB-6685): the same book names that chapter:verse explicitly; or a bare reference to it inherits that book (the last book named before it); or it appears bare and no reference names it under another book; or the pressed reference itself has no book.
 const isNamed=(N,bk,cv)=>{const f=N.get(cv);if(!f)return false;if(!bk||f.books.has(bk)||f.inh.has(bk))return true;return f.bare&&f.books.size===0;};
 const lastHead=(t,re)=>{let i=-1;for(const m of String(t||'').matchAll(re))i=m.index;return i;};
 const items=t=>String(t||'').split(/\n(?=\s*\**\s*\d+[.)]\s)/).filter(x=>/^\s*\**\s*\d+[.)]\s/.test(x));
 const side=(pressing,answering,headRe)=>{const i=lastHead(pressing,headRe);if(i<0)return {list:false,premises:[]};
  const list=String(pressing).slice(i);const N=namedIn(answering);
  const premises=items(list).map((x,k)=>{const lk=(x.match(/LINK\s+(\d+|none)\b/i)||[])[1]||null;const seen=new Set();const notNamed=[];let named=0;
   for(const r of refs(x)){const label=((r.book||r.ctx)?((r.book||r.ctx)+' '):'')+r.label;if(seen.has(label))continue;seen.add(label);
    if(r.cvs.some(cv=>isNamed(N,r.book||r.ctx||'',cv)))named++;else notNamed.push(label);}
   return {n:k+1,link:lk,verses:seen.size,named,notNamed};});
  return {list:true,premises};};
 const LF=String.fromCharCode(10);
 const DEF_RE=/UNSUPPORTED-L4 PREMISES/gi, CH_RE=/CHALLENGER.S UNSUPPORTED-L4 PREMISES/gi;
 const ledger=F=>({defender:side(F.gr2,F.cr3,DEF_RE),challenger:side(F.cr3,F.dr3,CH_RE),dCited:citedNotNamed([['[DR1]',F.gr1],['[DR2]',F.gr2]],[['[CR2]',F.cr2],['[CR3]',F.cr3]]),cCited:citedNotNamed([['[CR1]',F.cr1],['[CR2]',F.cr2],['[CR3]',F.cr3]],[['[DR2]',F.gr2],['[DR3]',F.dr3]])});
 const sideLines=(s,label)=>{if(!s.list)return [label+': no closing premise list found.'];
  return [label+':'].concat(s.premises.map(p=>'premise '+p.n+(p.link?' (LINK '+p.link+')':'')+': '+p.verses+' verse(s) carried; '+p.named+' named; NOT NAMED: '+(p.notNamed.length?p.notNamed.join(', '):'none')));};
 const judgeBlock=F=>{let L;try{L=ledger(F);}catch(e){return 'PRESSED-WITNESS LEDGER: not available this run; count witnesses as the rule says.';}
  return ['PRESSED-WITNESS LEDGER -- computed by the system from the transcript text, not by a model, by one rule for both sides. SCOPE: the verses carried by each numbered premise of the list that closes [DR2] (pressed against the defender) and of the CHALLENGER\'S UNSUPPORTED-L4 PREMISES list that closes [CR3] (pressed against the challenger), and whether the answering link round names each verse anywhere. The line beginning "cited in" under each side lists every verse the opposing side cited before that link round that no later round of the side that holds the link names (for the defender [CR2] or [CR3], for the challenger [DR2] or [DR3], later than the round that first cites the verse); which of those verses were quoted against a link or a listed premise is the judge\'s to decide. Not read by this ledger: ranges longer than 12 verses, references written with v., slash forms such as 24:16/43, and chapter-only references.']
   .concat(sideLines(L.defender,'AGAINST THE DEFENDER, answered in [CR3]'),[citedLine(L.dCited,'[DR1] or [DR2]','a later round of the defender, [CR2] or [CR3]')],sideLines(L.challenger,'AGAINST THE CHALLENGER, answered in [DR3]'),[citedLine(L.cCited,'[CR1], [CR2] or [CR3]','a later round of the challenger, [DR2] or [DR3]')],
   ['A verse marked NOT NAMED is unanswered by the rule; a verse marked NAMED may still be unanswered, and the judge decides that.']).join(LF);};
 const roundBlock=(pressing,re)=>{let s;try{s=side(pressing,'',re);}catch(e){return '';}
  if(!s.list||!s.premises.length)return '';
  return ['VERSES EACH PREMISE ABOVE CARRIES -- computed by the system from the list, not by a model:'].concat(s.premises.map(p=>'premise '+p.n+(p.link?' (LINK '+p.link+')':'')+': '+(p.notNamed.length?p.notNamed.join(', '):'(no verse reference)'))).join(LF);};
 // ORDER (A) (BB-6708, ruled BB-6712): every verse the opposing side cited in the rounds before a link round is listed for that link round and counted in the ledger; one rule, both sides; which verse was quoted against a link stays the judge's call.
 const citedLabels=t=>{const out=[];const seen=new Set();for(const r of refs(t)){if(!r.book)continue;const label=r.book+' '+r.label.replace(/[–—]/g,'-');if(seen.has(label))continue;seen.add(label);out.push({label,r});}return out;};
 const citedRounds=rounds=>{const seen=new Set();return rounds.map(([name,t])=>({name,items:citedLabels(t).filter(x=>{if(seen.has(x.label))return false;seen.add(x.label);return true;})}));};
 const citedBlock=(rounds,who)=>{let rs;try{rs=citedRounds(rounds);}catch(e){return '';}if(!rs.some(x=>x.items.length))return '';
  return ['EVERY VERSE '+who+' CITED BEFORE THIS LINK ROUND -- computed by the system from the transcript, not by a model; each verse is listed under the first round that cites it:'].concat(rs.map(x=>x.name+': '+(x.items.length?x.items.map(i=>i.label).join(', '):'none'))).join(LF);};
 // BB-6904 rev 12 (7379): a verse counts as named when any later round of the answering side names it, later than the round that first cites it.
 const citedNotNamed=(rounds,answers)=>{const O=['[CR1]','[DR1]','[CR2]','[DR2]','[CR3]','[DR3]'];const NA=answers.map(([k,t])=>[O.indexOf(k),namedIn(t)]);let total=0;const not=[];for(const x of citedRounds(rounds)){const at=O.indexOf(x.name);const Ns=NA.filter(a=>a[0]>at).map(a=>a[1]);for(const i of x.items){total++;if(!Ns.some(N=>i.r.cvs.some(cv=>isNamed(N,i.r.book,cv))))not.push(i.label);}}return {total,not};};
 const citedLine=(c,rounds,link)=>'cited in '+rounds+' and not named in '+link+' ('+c.not.length+' of '+c.total+'): '+(c.not.length?c.not.join(', '):'none');
 return {ledger,judgeBlock,roundBlock,citedBlock,DEF_RE,CH_RE};})();

const LEDGER=PWL.judgeBlock({cr1:F.cr1,gr1:F.gr1,cr2:F.cr2,gr2:F.gr2,cr3:F.cr3,dr3:F.dr3});
const NL=String.fromCharCode(10);
const KJVC=(()=>{let x=null;try{x=$('Quote Report').first().json;}catch(e){x=null;}
 if(!x||x.unavailable||!Array.isArray(x.items))return 'CITATION CHECK AGAINST THE KJV: not available this run; grade citations as usual.';
 const bad=x.items.filter(i=>i.status&&i.status!=='MATCHES'&&i.status!=='NOT CHECKED');
 const head='CITATION CHECK AGAINST THE KJV -- computed by the system from the KJV text, not by a model: '+x.checked+' quotations given with a reference; '+x.matches+' match the verse cited; '+bad.length+' do not; '+x.not_checked+' too short to check.';
 if(!bad.length)return head;
 return head+NL+bad.map(i=>i.side+' '+i.round+': cited '+i.ref+': "'+String(i.quote).slice(0,160)+'" -- '+i.status).join(NL)+NL+'RULE: a quotation whose words ARE AT another verse is real KJV text cited to the wrong place: name it as a citation error in your justification; it still counts as [L1] footing for the words quoted. A quotation whose wording is NOT FOUND in the book named, or whose cited verse does not exist, is NOT [L1] footing for any link that rests on it. A citation error by one side never counts for or against the other side.';})();

// ONE RULEBOOK (operator-approved 2026-10-04): the panel judges by the same layer rules, verdict definitions and standing
// definitions as the single judge (Build Independent Verdict, ODV1-A1). Rule text below is carried verbatim from that node;
// only the output form differs (strict JSON; the worked lines go in "reasoning").
let SYS=['You are ONE of three INDEPENDENT judges of a completed debate. You have not seen the other judges and you will not. Judge only what is in the transcript below. You are bound by the same layer rules as all debate participants, and by the same rulebook as every other judge of this debate.','','Grade each side by its ROLE; neither reading is presumed.','','Name people and things only in the KJV\'s own words or in plain English; no titles, honorifics or capitalised epithets the text does not use (it says \'the child\', not \'the Boy\'); every Greek or Hebrew word you use is followed by its plain English meaning.','','RETURN STRICT JSON AND NOTHING ELSE. No prose before or after it. No code fences.','{','  "verdict_tag": "HELD" | "PARTIAL" | "BROKEN",','  "defense_standing": "SELF-SUPPORTED" | "PROP-DEPENDENT" | "COLLAPSED",','  "challenge_standing": "SELF-SUPPORTED" | "PROP-DEPENDENT" | "COLLAPSED",','  "conceded_links": integer >= 0,','  "challenger_conceded_links": integer >= 0,','  "counted_premises_defender": array of integers -- the PRESSED-WITNESS LEDGER premise numbers (AGAINST THE DEFENDER) you counted in conceded_links; [] when none','  "counted_premises_challenger": array of integers -- the PRESSED-WITNESS LEDGER premise numbers (AGAINST THE CHALLENGER) you counted in challenger_conceded_links; [] when none','  "reasoning": string -- the worked grading: the RESULT line, the CLAUSE line, KEYSTONE, both standings with their justification, both conceded-link itemizations, COLLISION POINTS, the citation check, OUT-OF-ROUND CONCESSIONS, DEFENDER CHAIN MARK and CHALLENGER CHAIN MARK, in the forms the rulebook below gives, one per line (newlines escaped as \\n inside the JSON string)','}','','THESE TOKENS ARE EXACT AND THE SETS ARE CLOSED. A value outside them is a FAILED judgment, not a nuance, and it will be counted as unreadable. Do NOT return "UNKNOWN" and do NOT invent a fourth tag: an UNKNOWN tag is scored as unclean AND is invisible to the unrecognised-tag report, so it is the one answer that hides itself.','','verdict_tag MUST be the verdict word the VERDICT DEFINITIONS below give (first match wins). defense_standing, challenge_standing, conceded_links and challenger_conceded_links MUST equal the values your reasoning reaches under the rulebook; each counted_premises array MUST list exactly the premises its count counts.','','THE RULEBOOK','','JUDGE LAYER RULES:'+NL+'[L1]=KJV text. [L2]=Hebrew/Greek. [L3]=Cross-reference. [L4]=Inference -- flag explicitly.'+NL+'Evaluate ONLY what was argued in this transcript.',
"THE FRAMEWORK IS NOT A COMBATANT. The framework is the Rules of Engagement and Rules of Interaction -- Isaiah 28:10 method, the L1-L4 layer rules, the burden rule -- and it binds BOTH combatants equally. The debate is about the TOPIC. The DEFENDER holds a chain of interlocking citations on the topic; the CHALLENGER presses an opposing view and settles it only by breaking that chain. A claim by either side that restates resolved ground with its stating verses cited is not an overpress."+NL+"This debate was CHAIN-SCOPED (Isaiah 28:10 declared): judge whether the DEFENDER'S CHAIN on the topic survived as a chain -- isolated-link objections that never engage the chain do not break it. The rule cuts both ways: an objection that is itself a floating [L4] (no exhibited layer footing) cannot break a link that exhibits its footing. Name every floating [L4] on either side before weighing it; an inference admitted through the prior layers (Isaiah 28:10) is EVIDENCE, an inference that floats free of the text is not.",'',
'COUNTING RULE -- BINDING, read before grading: grade and COUNT only from the two LINK ROUND blocks above, [CR3] (defender) and [DR3] (challenger); an ANSWER to a pressed witness is read from any later round of the side that holds the link, its round 2 or its link round. The POST-DEBATE ANALYSIS block is CONTEXT ONLY and is NOT evidence of concession -- never take a count from it, and ignore the word "unanswered" wherever it appears there. In this format the challenger link round [DR3] is structurally LAST: no defender round follows it, so the defender being silent after [DR3] is procedural and is NEVER a challenger concession. A premise counts as CONCEDED only if the link round block itself states it as conceded, or exhibits no layer footing for it in that block. UNANSWERED WITNESS: a verse the other side quoted against a link or a listed premise in an earlier round (against the defender: [DR1] and [DR2]; against the challenger: [CR1], [CR2] and [CR3]) is ANSWERED when any later round of the side that holds the link (for the defender: [CR2] or [CR3]; for the challenger: [DR2] or [DR3]) quotes it or names it by reference and shows from the text why it does not overturn the link. Re-citing the link\'s own footing while passing over the witness pressed against it is not an answer. A premise whose pressed witness goes unanswered is UNEXHIBITED: it counts toward CONCEDED LINKS and the standings. In a debate a non-response is never neutral. A verse on a side\'s \'cited in\' line counts as an unanswered witness only when the judge quotes the sentence of the earlier round that pressed it against that link or a listed premise and names that round; a verse cited there but not pressed against the link does not count. A judge who grades a link BROKEN because the witnesses exclude, deny or establish something must quote the words that state it; where the quoted words, read in their own context and with the other verses the judge quotes, do not state it, the ground is the judge\'s own [L4] inference, and it counts only when the judge exhibits two lower layers ([L1]-[L3]) for it, as submitted evidence must; otherwise it is no ground for BROKEN, and the link is graded under the remaining rules. UNCHALLENGED: everything a side presents is open to challenge. A link or a witness the other side never challenged in any of its rounds stands as HELD for the side that presented it, and the silent side may not contest it in the verdict. A claim a side restates in its own link round is graded at the layer and with the footing it exhibits there; an earlier [L4] label of the same claim does not survive the restatement.'+NL+NL+'VERDICT DEFINITIONS -- apply these mechanically, first match wins; not your own scale.'+NL+"TERMS. DEFENDER LINKS: the links of the DEFENDER'S OWN DECLARED CHAIN as written in [CR1] under its anchored DECLARED CHAIN heading, numbered D1..Dn in that order; n = their number. The LAST declared link, Dn, is the conclusion link. THE ROUND 1 CHAIN GOVERNS. n, the numbering D1..Dn and the keystone Dn come from the DECLARED CHAIN in [CR1] only. A chain the defender declares again in a later round, re-seated, revised or extended, never changes n, the numbering or the keystone: a link added later is not a declared link, and a [CR1] link left out later is still declared. A challenger premise written LINK i: is graded against Di. A challenger premise written LINK none: is JUDGED but is OUTSIDE n and never changes it. The challenger's listed premise count is NOT n and is never substituted for it. CHALLENGER LINKS: the premises listed for the challenger in [DR3], numbered C1..Cm in [DR3] order. WITHDRAWN: a defender link that [CR3] itself states as conceded or withdrawn, wholly or on a stated condition; tag it CONCEDED (stated) or CONCEDED (conditional: <condition>). w = their number. Only the DECLARED links D1..Dn can enter w; a challenger premise written LINK none: is not a defender link and never enters w, however the defender treats it. No link is exempt from w as auxiliary, overreach, non-core or not load-bearing. A link is withdrawn or it is not. Pressure from the challenger's texts alone is not a withdrawal (w); a witness the side's later rounds leave unanswered is graded under UNANSWERED WITNESS and at the COLLISION POINTS. An UNEXHIBITED link counts toward CONCEDED LINKS and the standings, never toward w. BROKEN AT COLLISION: a defender link graded DEFENDER LINK BROKEN on the COLLISION POINTS lines; k = their number."+NL+'BROKEN-1: k >= 1 -- a listed defender link refuted from the text.'+NL+'BROKEN-2: 2w > n, OR the keystone link is WITHDRAWN.'+NL+'PARTIAL-1: w >= 1.'+NL+'PARTIAL-2: DEFENSE STANDING is COLLAPSED.'+NL+'HELD-1: none of the above.'+NL+'STANDINGS ARE GRADED BY THEIR OWN RULES ONLY. DEFENSE STANDING and CHALLENGE STANDING are each decided by their own definitions below and by nothing else. Any standing is legal with any CLAUSE: the clauses are tried in order and the first match wins, so a COLLAPSED standing under BROKEN-1, BROKEN-2 or PARTIAL-1 is correct and changes no clause. Never choose a standing, a count or a clause to agree with another line, a check or an expected result: when 2c > L the standing is COLLAPSED, whatever the clause.'+NL+'A SIDE WITH A COUNTED LINK IS NOT SELF-SUPPORTED. If CONCEDED LINKS is 1 or more, DEFENSE STANDING is PROP-DEPENDENT, or COLLAPSED when 2c > L; if CHALLENGER CONCEDED LINKS is 1 or more, CHALLENGE STANDING is PROP-DEPENDENT, or COLLAPSED when 2c > L. SELF-SUPPORTED requires a count of 0 for that side: every premise listed against it exhibited its footing or was VOID.'+NL+'Line 1: the verdict word first (HELD, PARTIAL or BROKEN), then 2-4 sentences with [L1][L2][L3][L4] tags.'+NL+'Line 2, exactly: RESULT: DEFENDER WINS | CHALLENGER WINS | UNDERDETERMINED -- one sentence a reader with no background understands. BROKEN gives CHALLENGER WINS. HELD gives DEFENDER WINS only if CHALLENGE STANDING is not SELF-SUPPORTED or at least one collision is graded CHALLENGER LINK BROKEN. Every other case gives UNDERDETERMINED.'+NL+'Line 3, exactly: CLAUSE: <BROKEN-1 | BROKEN-2 | PARTIAL-1 | PARTIAL-2 | HELD-1> -- n=<n> w=<w> k=<k>'+NL+NL+'Then SIX MORE mandatory lines, exactly in these forms:'+NL+'KEYSTONE: D<n> -- WITHDRAWN | BROKEN | STANDS -- name the LAST declared link, Dn, which is the conclusion link, and give its state. WITHDRAWN if it is withdrawn or conceded; BROKEN if it is graded DEFENDER LINK BROKEN at a collision; STANDS otherwise. The number after D MUST equal the n on the CLAUSE line, and the state MUST match that link\'s own D<n> entry.'+NL+'DEFENSE STANDING: SELF-SUPPORTED | PROP-DEPENDENT | COLLAPSED -- L=<L> c=<c> -- grade the DEFENDER only, using the STATED/INFERRED tags and the [CR3] LINK ROUND. SELF-SUPPORTED = every listed defender claim is carried by its layer stack -- each [L4] exhibits the [L1]/[L2]/[L3] footing it rests on (at least two prior layers exhibited; a shown chain counts equally). PROP-DEPENDENT = the defense survived only because listed [L4]s were allowed to stand WITHOUT exhibiting their prior-layer footing (floating inference; links conceded/unexhibited in the LINK ROUND). COLLAPSED = by count, mandatory, not discretionary: 2c > L, where L is the number of premises the CHALLENGER listed AGAINST the defender (the UNSUPPORTED-L4 PREMISES list that closes [DR2]) and c is the number of those the defender CONCEDED or left UNEXHIBITED in its LINK ROUND [CR3]. The premises the defender itself lists against the challenger at the end of [CR3] (CHALLENGER\'S UNSUPPORTED-L4 PREMISES) are the challenger\'s burden and NEVER enter the defender\'s L, c, CONCEDED LINKS or DEFENSE STANDING. FORFEIT: if the challenger listed no premises against the defender (an empty list, or PREMISE COUNT: 0), then L = 0, c = 0, CONCEDED LINKS is 0, DEFENSE STANDING cannot be COLLAPSED, and you add the line LINK ROUND FORFEITED: CHALLENGER -- no premises were listed against the defender. A LINK ROUND answer that neither exhibits the premise\'s layer footing nor concedes counts as CONCEDED. A tie (2c = L) is NOT COLLAPSED. COLLAPSED is reached by this count only; SELF-SUPPORTED against PROP-DEPENDENT is your judgment as defined above. A listed premise is countable only as charged IF the list carries the opponent\'s verbatim quote that states it; a premise listed without a verbatim quote, or charged in terms stronger than its quote, is VOID -- it counts for neither side, and a CONCEDED answer to a void premise is NOT a concession: name it VOID in your itemization and exclude it from every count and standing. A link honestly conceded as held inference still counts toward the count but note it as disciplined, not evasive. One sentence of justification.'+NL+'CONCEDED LINKS: <integer> -- the count of challenger-listed premises the defender CONCEDED or failed to exhibit its layer footing in [CR3]. Itemize the counted links and tag each with the clause that fired: CONCEDED (stated) when the block itself states the surrender; UNEXHIBITED (no footing offered) when the block asserted the link and offered no layer footing at all. A link whose block exhibits at least two prior layers of footing and shows the chain from them to the link is SUPPORTED and is not counted, even when no cited verse states the link\'s conclusion in words: an [L4] is an inference by definition, and demanding a verse that states it is the retired stating-verse test, which is never applied. When the count is lower than the number of links, name which links are counted and which are spared. Both tags count toward the single integer; keep the tags distinct in the itemization and do not report more than one number.'+NL+'CHALLENGE STANDING: SELF-SUPPORTED | PROP-DEPENDENT | COLLAPSED -- L=<L> c=<c> -- grade the CHALLENGER only, using the challenger\'s STATED/INFERRED tags and the [DR3] LINK ROUND. SELF-SUPPORTED = every listed objection is carried by its layer stack -- each [L4] exhibits the [L1]/[L2]/[L3] footing it rest